import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Model Studio glossary","description":"Model Studio, Qwen, and Lingma are not the same product. Neither are the three protocols, two plans, or two CLIs.","frontmatter":{"title":"Model Studio glossary","description":"Model Studio, Qwen, and Lingma are not the same product. Neither are the three protocols, two plans, or two CLIs.","domain":"product","tags":["model-platform"],"role":"glossary"},"headers":[],"relativePath":"products/bailian/bailian-glossary.md","filePath":"products/bailian/bailian-glossary.md","lastUpdated":1787110548000}'),l={name:"products/bailian/bailian-glossary.md"};function n(d,t,s,i,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="model-studio-glossary" tabindex="-1">Model Studio glossary <a class="header-anchor" href="#model-studio-glossary" aria-label="Permalink to &quot;Model Studio glossary&quot;">​</a></h1><p>No procedures. Just the collisions. Paths live on the <a href="./index.html">map</a>.</p><h2 id="model-studio" tabindex="-1">Model Studio <a class="header-anchor" href="#model-studio" aria-label="Permalink to &quot;Model Studio&quot;">​</a></h2><p><strong>What</strong>: Alibaba Cloud&#39;s model-service and application platform. Chinese name 百炼. APIs, console apps, subscription plans. <a href="https://www.alibabacloud.com/help/en/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">Intro</a></p><p><strong>Not</strong>: the Tongyi chat window, the Lingma IDE, or ECS / OSS.</p><p><strong>Why this handbook exists</strong>: a front-end that calls Qwen talks to this platform&#39;s API and billing, not to the chat site.</p><h2 id="qwen" tabindex="-1">Qwen <a class="header-anchor" href="#qwen" aria-label="Permalink to &quot;Qwen&quot;">​</a></h2><p><strong>What</strong>: Alibaba&#39;s model family, and a separate chat product. FAQ: Model Studio is a platform that <em>includes</em> the Qwen series. <a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></p><p><strong>Here</strong>: only &quot;a model you can call on Studio&quot;. Chat-product prose is #83.</p><h2 id="lingma-qoder-cn" tabindex="-1">Lingma / Qoder CN <a class="header-anchor" href="#lingma-qoder-cn" aria-label="Permalink to &quot;Lingma / Qoder CN&quot;">​</a></h2><p><strong>What</strong>: Alibaba Cloud&#39;s coding assistant / standalone IDE. Current official name <strong>Qoder CN (formerly Lingma)</strong>. <a href="https://help.aliyun.com/zh/model-studio/lingma-agent" target="_blank" rel="noreferrer">Attach page</a></p><p><strong>Relation</strong>: can take a Studio Token Plan / Coding Plan / PAYG key. Official: Enterprise cannot attach Studio.</p><p><strong>Here</strong>: one line. Full tutorial is #84.</p><h2 id="dashscope" tabindex="-1">DashScope <a class="header-anchor" href="#dashscope" aria-label="Permalink to &quot;DashScope&quot;">​</a></h2><p><strong>What</strong>: the old API brand. The env var is still <code>DASHSCOPE_API_KEY</code>. US hosts still say <code>dashscope-us.aliyuncs.com</code>. Coding Plan still mentions <code>dashscope.aliyuncs.com</code>.</p><p><strong>Not</strong>: a second product you activate beside Model Studio.</p><h2 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h2><p><strong>What</strong>: a container that isolates project / team resources and ACL. <code>{WorkspaceId}</code> in the new MaaS URLs is this ID. <a href="https://help.aliyun.com/zh/model-studio/first-api-call-to-qwen" target="_blank" rel="noreferrer">First API call</a>, <a href="https://help.aliyun.com/zh/model-studio/get-api-key" target="_blank" rel="noreferrer">Get an API key</a></p><p><strong>Official ACL</strong>:</p><ul><li>Keys in the same workspace share the same rights. You do not split keys by text vs image.</li><li>Default workspace: all standard models + apps in that workspace.</li><li>Child workspace: only authorized standard models + its own apps.</li><li>Fine-tuned models: only the workspace they live in.</li></ul><p>Primary accounts see every workspace&#39;s keys. RAM users see only workspaces they joined.</p><h2 id="three-call-protocols" tabindex="-1">Three call protocols <a class="header-anchor" href="#three-call-protocols" aria-label="Permalink to &quot;Three call protocols&quot;">​</a></h2><p>The model list often prints three hosts for one ID:</p><table tabindex="0"><thead><tr><th>Protocol</th><th>Path</th><th>When</th></tr></thead><tbody><tr><td>OpenAI-compatible</td><td><code>/compatible-mode/v1</code></td><td>Existing <code>openai</code> SDK, most desktop clients</td></tr><tr><td>Anthropic-compatible</td><td><code>/apps/anthropic</code></td><td>Tools that speak Messages (Claude Code, …)</td></tr><tr><td>DashScope</td><td><code>/api/v1</code></td><td>Official DashScope SDK, some multimodal generate APIs</td></tr></tbody></table><p>Source: <a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">Models</a>. The three hosts are <strong>not</strong> interchangeable. Plans add a fourth dedicated host.</p><h2 id="token-plan-vs-coding-plan" tabindex="-1">Token Plan vs Coding Plan <a class="header-anchor" href="#token-plan-vs-coding-plan" aria-label="Permalink to &quot;Token Plan vs Coding Plan&quot;">​</a></h2><p>Two Studio subscriptions. <strong>No migrate / upgrade path between them.</strong> <a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a></p><table tabindex="0"><thead><tr><th></th><th>Token Plan</th><th>Coding Plan</th></tr></thead><tbody><tr><td>Meter</td><td>Credits</td><td>Request counts</td></tr><tr><td>Official stance (2026-08)</td><td>Preferred for new buys</td><td>Lite stopped; Pro limited</td></tr><tr><td>Personal vs team</td><td>Personal has a 7-day window; Team is per-seat and commits not to train</td><td>Page is Pro-centric</td></tr><tr><td>Data</td><td>Personal used to improve the service; Team commits not to</td><td>Inputs and outputs used to improve the service</td></tr><tr><td>Allowed use</td><td>Tools that speak OpenAI / Anthropic</td><td><strong>Coding tools only</strong>, not your backend API</td></tr></tbody></table><p>&quot;We never train on your data&quot; in the FAQ / international intro is the short version. The intro&#39;s <strong>Important</strong> box and the two plan pages win.</p><h2 id="agent-1-0-vs-2-0" tabindex="-1">Agent 1.0 vs 2.0 <a class="header-anchor" href="#agent-1-0-vs-2-0" aria-label="Permalink to &quot;Agent 1.0 vs 2.0&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>1.0</th><th>2.0</th></tr></thead><tbody><tr><td>Scheduling</td><td>Retrieve the knowledge base, then maybe MCP</td><td>Knowledge base and MCP are tools; the model orders them</td></tr><tr><td>Trace</td><td>Final answer only</td><td>Plan → act → reflect</td></tr><tr><td>Migration</td><td>—</td><td><strong>Cannot</strong> upgrade 1.0; create a new app</td></tr></tbody></table><p>Source: <a href="https://help.aliyun.com/zh/model-studio/new-single-agent-application" target="_blank" rel="noreferrer">Agent 2.0</a>. Official default when you have no 1.0 dependency.</p><p>A workflow is a different console app type (a fixed graph), not another name for Agent 2.0. <a href="https://help.aliyun.com/zh/model-studio/workflow-application/" target="_blank" rel="noreferrer">Workflow</a></p><h2 id="knowledge-base-rag" tabindex="-1">Knowledge base (RAG) <a class="header-anchor" href="#knowledge-base-rag" aria-label="Permalink to &quot;Knowledge base (RAG)&quot;">​</a></h2><p>Retrieve private documents, then generate. Billed separately from model inference; no savings plan or resource pack. <a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">Intro</a></p><p>One official anti-hallucination tool (FAQ). Mechanism lives in <a href="/tech/fundamentals/LLM.html">LLM fundamentals</a>.</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>Model Context Protocol. Studio agents and workflows can attach official or custom MCP servers. <a href="https://help.aliyun.com/zh/model-studio/mcp-introduction" target="_blank" rel="noreferrer">MCP intro</a></p><p>Some official MCPs (image, video, speech, web search) bill on their own. Custom MCP has basic / turbo time-based prices. Whether deploy is still &quot;temporarily free&quot; is that page&#39;s job.</p><h2 id="model-studio-cli-vs-alibaba-cloud-cli" tabindex="-1">Model Studio CLI vs Alibaba Cloud CLI <a class="header-anchor" href="#model-studio-cli-vs-alibaba-cloud-cli" aria-label="Permalink to &quot;Model Studio CLI vs Alibaba Cloud CLI&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Model Studio CLI</th><th>Alibaba Cloud CLI plugin</th></tr></thead><tbody><tr><td>Package / command</td><td>npm <code>bailian-cli</code>; <code>bl</code> / <code>bailian</code></td><td><code>aliyun bailian …</code></td></tr><tr><td>Job</td><td>Local agent calls to models and multimodal tools</td><td>OpenAPI: categories, files, connectors</td></tr><tr><td>Docs</td><td><a href="https://bailian.aliyun.com/cli/install.md" target="_blank" rel="noreferrer">install.md</a></td><td><a href="https://next.api.aliyun.com/api-tools/cli/bailian/2023-12-29" target="_blank" rel="noreferrer">OpenAPI CLI</a></td></tr></tbody></table><p>Wrong binary: <code>aliyun bailian list-file</code> works, <code>bl text chat</code> does not exist.</p><h2 id="high-code-apps" tabindex="-1">High-code apps <a class="header-anchor" href="#high-code-apps" aria-label="Permalink to &quot;High-code apps&quot;">​</a></h2><p>Deploy a Python project as a managed backend. Official: <a href="https://help.aliyun.com/zh/model-studio/rich-code-application/" target="_blank" rel="noreferrer">high-code apps</a>. Axis B — no tutorial here.</p>',44)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
